head.script:
scwin.screenId = "jlddst15200";

///////// 1. 변수 및 선언 영역 /////////

scwin.title_of_account1 = $c.util.getComponent('title_of_account1');

scwin.title_of_account2 = $c.util.getComponent('title_of_account2');


///////// 2. 초기화 영역 /////////

// 현재 시각 파생값 충전 — as-is JSP 계산분(서버 데이터 아님). 진입점 선두 단계.
/**
 * @method
 * @name scwin.init_nowVars
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_nowVars = function () {
    const pc = $c.util.getComponent('dma_pageContext');
    if (!pc || !pc.set || !pc.get) { return; }
    if (!pc.get("nowYear")) { pc.set("nowYear", $c.date.getServerDateTime("yyyy")); }
};

// 연도 선택 항목 — as-is 가 서버에서 그리던 범위를 화면에서 세운다(값 원천 = dma_pageContext.nowYear).
/**
 * @method
 * @name scwin.init_yearItems
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_yearItems = function () {
    const pc = $c.util.getComponent("dma_pageContext");
    const ny = Number(pc && pc.get ? pc.get("nowYear") : 0);
    if (!ny) { console.error("[sdd] 연도 선택 — nowYear 미충전(init_nowVars 앞에서 불렸다)"); return 0; }
    {
        const s = $c.util.getComponent("slc_fiscalyear");
        if (!s || typeof s.addItem !== "function") { console.error("[sdd] 연도 선택 대상 부재: " + "slc_fiscalyear"); }
        else {
            if (typeof s.removeAll === "function") { s.removeAll(); }
            for (let i = 0; i <= (ny - 1996); i++) {
                const y = String(ny - (i - (0)) * 1);
                s.addItem(y, y);
            }
            s.setValue(String((ny - 1)));
        }
    }
    return 1;
};

/**
 * @method
 * @name scwin.init
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init = async function () {
    /* sdd-asis-lifecycle:begin init — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    scwin.title_of_account2.setStyle("display", "none");
    await scwin.fnSearch(false);
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.init_pageBody
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_pageBody = async function () {
    try {
        /* sdd-asis-lifecycle:begin onpageload — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await scwin.init();
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jlddst15200.onpageload' }); }
};

// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

scwin.finstat = undefined; try { scwin.finstat = /* sdd-asis-lifecycle:begin finstat — as-is 원문 본문(전환 이관 · 포팅 적용됨) */new Array("A010","A040","A080","A090","A100","A110","A120","A130","A140","A160","A170","A180","A190","A200")/* sdd-asis-lifecycle:end */; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jlddst15200' }); }

scwin.finrate = undefined; try { scwin.finrate = /* sdd-asis-lifecycle:begin finrate — as-is 원문 본문(전환 이관 · 포팅 적용됨) */new Array("B010","B020","B030","B040","B050","B060","B080","B090","B100","B110")/* sdd-asis-lifecycle:end */; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jlddst15200' }); }

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_nowVars();
        scwin.init_yearItems();
        await scwin.init_pageBody();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jlddst15200.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////

/**
