*/
scwin.slc_ordergubun_onchange = function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin slc_ordergubun_onchange — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        scwin.changeOrder(); return false;
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jlddst15200.slc_ordergubun_onchange' }); }
};

