*/
scwin.slc_basisAccnt_onchange = function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin slc_basisAccnt_onchange — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        scwin.checkAccount(selfVar.id);
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jlddst15200.slc_basisAccnt_onchange' }); }
};

/**
 * @event
 * @name scwin.btn_changeTitleOfAccountPanel_onclick
