 * @returns
 * @hidden N
*/
scwin.btn_changeTitleOfAccountPanel_onclick = function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin btn_changeTitleOfAccountPanel_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        scwin.changeTitleOfAccountPanel(); return false;
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jlddst15200.btn_changeTitleOfAccountPanel_onclick' }); }
};

/**
 * @event
 * @name scwin.ipt_chAll1_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.ipt_chAll1_onclick = function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin ipt_chAll1_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        scwin.changeAllCheckState()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jlddst15200.ipt_chAll1_onclick' }); }
};

/**
 * @event
 * @name scwin.ipt_chAll2_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.ipt_chAll2_onclick = function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin ipt_chAll2_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        scwin.changeAllCheckState()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jlddst15200.ipt_chAll2_onclick' }); }
};

/**
 * @event
 * @name scwin.btn_fnSearch_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.btn_fnSearch_onclick = async function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin btn_fnSearch_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await scwin.fnSearch(false); return false;
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jlddst15200.btn_fnSearch_onclick' }); }
};

/**
 * @event
 * @name scwin.btn_fnDownload_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
